"""Inspect SQLite databases located in this script's folder (schema only)."""

import os
import sqlite3
from pathlib import Path

HERE = Path(__file__).resolve().parent

db_files = sorted(
    p
    for p in HERE.iterdir()
    if p.is_file() and p.suffix.lower() in {".db", ".sqlite", ".sqlite3"}
)

if not db_files:
    print("NO_DB_FILES_FOUND")
    print("Files present:", sorted(p.name for p in HERE.iterdir() if p.is_file()))
else:
    for db in db_files:
        print(f"DB: {db.name} ({db.stat().st_size} bytes)")
        try:
            with sqlite3.connect(db) as conn:
                conn.row_factory = sqlite3.Row
                cur = conn.cursor()
                tables = cur.execute(
                    "SELECT name FROM sqlite_master WHERE type='table' ORDER BY name"
                ).fetchall()
                for t in tables:
                    tname = t["name"]
                    cols = cur.execute(f'PRAGMA table_info("{tname}")').fetchall()
                    col_desc = ", ".join(
                        f"{c['name']} {c['type']}" for c in cols
                    )
                    print(f"  TABLE {tname}: {col_desc}")
        except sqlite3.Error as exc:
            print(f"  ERROR reading {db.name}: {exc}")
        print()

